from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    row_divs = [r for r in range(h) if len(set(grid[r])) == 1]
    col_divs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # Locate the rail that divides the grid into two equally sized panels.
    horizontal = False
    sep = None
    for r in row_divs:
        if r == h - r - 1:
            sep, horizontal = r, True
            break
    if sep is None:
        for c in col_divs:
            if c == w - c - 1:
                sep, horizontal = c, False
                break
    if sep is None:
        raise ValueError('could not find equal-panel divider')

    if horizontal:
        first, second = grid[:sep], grid[sep + 1:]
    else:
        first = [row[:sep] for row in grid]
        second = [row[sep + 1:] for row in grid]

    first_colors = {v for row in first for v in row}
    second_colors = {v for row in second for v in row}
    shared = first_colors & second_colors
    if len(shared) != 1:
        raise ValueError(f'expected one shared panel color, got {shared}')
    background = next(iter(shared))
    return [[3 if first[r][c] == second[r][c] else background
             for c in range(len(first[0]))] for r in range(len(first))]


